mapper.select:
SELECT /*SQL-ID : isry.couns.cyberdscsnmnla.mapper.CyberMnlaListMapper : 사이버상담 매뉴얼 및 자료실(조회) */ AA.MNLA_NO /* 매뉴얼번호 */ , AA.MNLA_NM /* 매뉴얼명 */ , AA.MNLA_CN /* 매뉴얼내용 */ , AA.ATFINO /* 첨부파일번호 */ , AA.USE_YN /* 사용여부 */ , AA.CYBER_DSCSN_MNLA_LCLAS_SE_CD /* 내담자대분류코드 */ , AA.CYBER_DSCSN_MNLA_MLSFC_SE_CD /* 내담자중분류코드 */ , AA.CYBER_DSCSN_MNLA_SCLAS_SE_CD /* 내담자소분류코드 */ , AA.FRST_RGTR_ID /* 최초등록아디디 */ , to_char(AA.FRST_REG_DT,'YYYY-MM-DD') AS FRST_REG_DT /* 최초등록일시 */ , AA.LAST_MDFR_ID /* 최종수정아이디 */ , AA.LAST_MDFCN_DT /* 최종수정일시 */ , (SELECT C##RG.DEC_B64(CC.FLNM_ENCPT) FROM SAA200 AS BB , SCA100 AS CC WHERE 1=1 AND AA.FRST_RGTR_ID = BB.USER_ID AND BB.ENFSN_NO = CC.ENFSN_NO AND CC.DEL_YN = 'N' ) AS NAME , COUNT(*) OVER() AS TOTAL_COUNT FROM AYA100 AS AA WHERE 1=1
AND CYBER_DSCSN_MNLA_LCLAS_SE_CD = #{CYBER_DSCSN_MNLA_LCLAS_SE_CD}
AND CYBER_DSCSN_MNLA_MLSFC_SE_CD = #{CYBER_DSCSN_MNLA_MLSFC_SE_CD}
AND CYBER_DSCSN_MNLA_SCLAS_SE_CD = #{CYBER_DSCSN_MNLA_SCLAS_SE_CD}
AND DEL_YN = 'N' OFFSET #{START_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY

mapper.insert:


      SELECT AYA100_SQ01.CURRVAL AS MNLA_NO
      FROM DUAL


INSERT INTO AYA100 (/*SQL-ID : isry.couns.cyberdscsnmnla.mapper.CyberMnlaListMapper : 사이버상담 매뉴얼 및 자료실(등록) */
            MNLA_NO       /* 매뉴얼번호 */
        ,   MNLA_NM     /* 매뉴얼명 */
        ,   MNLA_CN     /* 매뉴얼내용 */

        ,   ATFINO      /* 첨부파일번호 */

        ,   DEL_YN      /* 사용여부 */
        ,   CYBER_DSCSN_MNLA_LCLAS_SE_CD        /* 내담자대분류코드 */
        ,   CYBER_DSCSN_MNLA_MLSFC_SE_CD        /* 내담자중분류코드 */
        ,   CYBER_DSCSN_MNLA_SCLAS_SE_CD        /* 내담자소분류코드 */
        ,   FRST_RGTR_ID        /* 최초등록아디디 */
        ,   FRST_REG_DT     /* 최초등록일시 */
        ,   LAST_MDFR_ID        /* 최종수정아이디 */
        ,   LAST_MDFCN_DT       /* 최종수정일시 */
)VALUES(
            AYA100_SQ01.NEXTVAL
        ,   #{MNLA_NM}
        ,   #{MNLA_CN}

        ,   #{ATFINO}

        ,   'N'
        ,   '02'
        ,   #{CYBER_DSCSN_MNLA_MLSFC_SE_CD} 
        ,   #{CYBER_DSCSN_MNLA_SCLAS_SE_CD}  
        ,   #{FRST_RGTR_ID}
        ,   SYSDATE
        ,   #{LAST_MDFR_ID}
        ,   SYSDATE
        )
